from flask import Flask, request
app = Flask(__name__)

@app.route("/")
def home():
    return "Hello!"

@app.route("/about")
def about():
    name = request.args.get("name")
    bio = request.args.get("bio")

    html = f"""
    <h1>{name}</h1>
    <p>{bio}</p>
    """
    return html

if __name__ == "__main__":
    app.run()
